package com.gbconnected.users.functions; import com.gbconnected.users.domain.UserIdentity; import com.microsoft.azure.functions.*; import com.microsoft.azure.functions.annotation.*; import java.util.*;
public class UserFunctions {private static final String C="X-Correlation-Id";
 @FunctionName("users-me-organizations")public HttpResponseMessage orgs(@HttpTrigger(name="req",methods={HttpMethod.GET},route="v1/me/organizations",authLevel=AuthorizationLevel.FUNCTION)HttpRequestMessage<Optional<String>>r,ExecutionContext x){try{UserIdentity u=FunctionCallerIdentityResolver.resolve(r);return json(r,HttpStatus.OK,FunctionRuntime.RUNTIME.userAccess().organizations(u));}catch(SecurityException e){return err(r,HttpStatus.UNAUTHORIZED,"Unauthorized");}}
 @FunctionName("users-me-plants")public HttpResponseMessage plants(@HttpTrigger(name="req",methods={HttpMethod.GET},route="v1/me/organizations/{organizationId}/plants",authLevel=AuthorizationLevel.FUNCTION)HttpRequestMessage<Optional<String>>r,@BindingName("organizationId")String raw,ExecutionContext x){try{long id=Long.parseLong(raw);UserIdentity u=FunctionCallerIdentityResolver.resolve(r);return json(r,HttpStatus.OK,FunctionRuntime.RUNTIME.userAccess().plants(u,id));}catch(NumberFormatException e){return err(r,HttpStatus.BAD_REQUEST,"organizationId must be numeric");}catch(SecurityException e){return err(r,HttpStatus.UNAUTHORIZED,"Unauthorized");}}
 @FunctionName("users-whoami")public HttpResponseMessage who(@HttpTrigger(name="req",methods={HttpMethod.GET},route="v1/debug/whoami",authLevel=AuthorizationLevel.FUNCTION)HttpRequestMessage<Optional<String>>r,ExecutionContext x){try{return json(r,HttpStatus.OK,FunctionCallerIdentityResolver.resolve(r));}catch(SecurityException e){return err(r,HttpStatus.UNAUTHORIZED,"Unauthorized");}}
 @FunctionName("users-health")public HttpResponseMessage health(@HttpTrigger(name="req",methods={HttpMethod.GET},route="health",authLevel=AuthorizationLevel.ANONYMOUS)HttpRequestMessage<Optional<String>>r,ExecutionContext x){try{FunctionRuntime.RUNTIME.healthCheck();return json(r,HttpStatus.OK,Map.of("status","UP"));}catch(Exception e){return err(r,HttpStatus.SERVICE_UNAVAILABLE,"Database unavailable");}}
 private String corr(HttpRequestMessage<?>r){return r.getHeaders().entrySet().stream().filter(e->e.getKey().equalsIgnoreCase(C)).map(Map.Entry::getValue).filter(v->v!=null&&!v.isBlank()).findFirst().orElseGet(()->UUID.randomUUID().toString());}private HttpResponseMessage json(HttpRequestMessage<?>r,HttpStatus s,Object b){return r.createResponseBuilder(s).header("Content-Type","application/json").header(C,corr(r)).body(FunctionJson.GSON.toJson(b)).build();}private HttpResponseMessage err(HttpRequestMessage<?>r,HttpStatus s,String d){String id=corr(r);return r.createResponseBuilder(s).header("Content-Type","application/problem+json").header(C,id).body(FunctionJson.GSON.toJson(Map.of("status",s.value(),"title",s.name(),"detail",d,"correlationId",id))).build();}
}
